    Pw m -> mem_inv asegs m -> as_RFS H ((5, ff, fp) :: LF) m ->
    evt asegs sn_Pok (MS R F (Z_to_bv 64 LbA_SnFind.SNF_FOUND) fc None m (seg_rom asegs)).
